drawSceneObjects=function(){sceneObjects.forEach(o=>{let s=o.scale||1,cat=(o.category||'').toLowerCase(),d=o.dimensions||{},base=cat.includes('ambiente')?{width:3,depth:3,height:8}:cat.includes('escenario')?{width:14,depth:5,height:4}:{width:6,depth:3,height:1.2},w=(d.width||base.width)*s,dep=(d.depth||base.depth)*s,h=(d.height||base.height)*s;if(cat.includes('ambiente')){sceneBox(o.x,o.y,w,dep,h,'#6b432f',o.rotation||0);let p=project(o.x,o.y,h);ctx.save();ctx.fillStyle='#3d9b5b';ctx.beginPath();ctx.arc(p.x,p.y,18*s,0,Math.PI*2);ctx.fill();ctx.restore()}else if(cat.includes('escenario')){sceneBox(o.x,o.y,w,dep,h*.5,'#65748b',o.rotation||0);sceneBox(o.x,o.y-2*s,w*.85,dep*.6,h*.75,'#7d8da3',o.rotation||0)}else sceneBox(o.x,o.y,w,dep,h,'#b07a4d',o.rotation||0);if(o.src&&typeof Image!=='undefined'){if(!logoImages[o.id]){let image=new Image();image.onload=draw;image.src=o.src;logoImages[o.id]=image}let image=logoImages[o.id];if(image&&image.complete){let p=project(o.x,o.y,h*.75),size=Math.max(25,35*s);ctx.save();ctx.globalAlpha=.8;ctx.drawImage(image,p.x-size/2,p.y-size/2,size,size);ctx.restore()}}})};
