function renderEnhancedRouteList(){let box=$('#routeList');if(!box)return;box.innerHTML='';route.forEach((n,i)=>{let d=document.createElement('div');d.className='item';d.dataset.routeIndex=i;let label=document.createElement('span');label.className='route-entry-label';label.textContent=routeLabel(n);let badge=document.createElement('span');badge.className='badge';badge.textContent=i+1;let actions=document.createElement('span');actions.className='route-entry-actions';let up=document.createElement('button'),down=document.createElement('button');up.className='btn route-order-btn';down.className='btn route-order-btn';up.textContent='↑';down.textContent='↓';up.title='Subir elemento';down.title='Bajar elemento';up.disabled=i===0;down.disabled=i===route.length-1;up.onclick=e=>{e.stopPropagation();moveRouteEntry(i,-1)};down.onclick=e=>{e.stopPropagation();moveRouteEntry(i,1)};actions.append(up,down);d.append(badge,label,actions);d.onclick=()=>{routeSelection=n;selected=null;updateUI();draw()};if(n===routeSelection)d.classList.add('active');box.appendChild(d)})}
