autoOrder=function(){let nodes=courseObstacleNodes(),links=route.filter(n=>n.kind==='connection'&&n.fromObstacleId&&n.toObstacleId);if(nodes.length<2){status('Añade al menos 2 obstáculos al recorrido');return}let start=route.find(n=>n.kind==='point'&&n.marker==='start'),finish=route.find(n=>n.kind==='point'&&n.marker==='finish'),near=p=>nodes.slice().sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0],cur=start?near(start):nodes[0],ordered=[],used=new Set;while(cur&&!used.has(cur.objectId)){ordered.push(cur);used.add(cur.objectId);let l=links.find(n=>n.fromObstacleId===cur.objectId&&!used.has(n.toObstacleId));cur=l?nodes.find(n=>n.objectId===l.toObstacleId):null}nodes.filter(n=>!used.has(n.objectId)).forEach(n=>ordered.push(n));let course=[];ordered.forEach((n,i)=>{course.push(n);let next=ordered[i+1],l=next&&links.find(x=>x.fromObstacleId===n.objectId&&x.toObstacleId===next.objectId);if(l)course.push(l)});if(start)course.unshift(start);if(finish)course.push(finish);let extras=route.filter(n=>!['obstacle','connection','point'].includes(n.kind));history();route=[...course,...extras];ordered.forEach((n,i)=>{let o=objects.find(x=>x.id===n.objectId);if(o&&!o.manualNum)o.num=String(i+1)});routeSelection=null;updateUI();draw();status('Recorrido ordenado; puntos verdes conservados')};
