startExecution=function(){let items=[];if(allRoutePoints().length>1)items.push({kind:'courseRun',id:'course',color:executionColor,width:executionWidth,dash:executionDash});route.filter(n=>['line','curve','connection','circle'].includes(n.kind)).forEach(n=>items.push(n));if(!items.length){status('No hay líneas ni recorrido para ejecutar');return}executionQueue=items;executionIndex=0;executionProgress=0;executionRunning=true;anim=false;$('#play').textContent='⏸ Pausar';status('Ejecución iniciada en el orden de producción')};
drawExecutionOverlay=function(){let n=executionQueue[executionIndex];if(!n)return;let shape=n.kind==='courseRun'?catmull(allRoutePoints(),18):n.kind==='line'?nodePoints(n):n.kind==='circle'?nodePoints(n):catmull(nodePoints(n),18);if(shape.length<2)return;let count=Math.max(2,Math.ceil(shape.length*executionProgress)),pts=shape.slice(0,count).map(p=>project(p.x,p.y,.18));ctx.save();ctx.strokeStyle=executionColor;ctx.lineWidth=executionWidth;ctx.setLineDash(executionDash==='dashed'?[12,9]:executionDash==='dotted'?[3,8]:[]);ctx.shadowColor=executionColor;ctx.shadowBlur=10;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.restore();if(pts.length>1)arrow(shape[count-2],shape[count-1],executionColor)};
